package com.farmdirect.dao;
import com.farmdirect.model.Product; import com.farmdirect.util.DB; import java.sql.*; import java.util.*;
public class ProductDAO {
 private Product map(ResultSet r)throws SQLException{return new Product(r.getInt("id"),r.getInt("farmer_id"),r.getString("name"),r.getString("category"),r.getDouble("price"),r.getInt("stock"),r.getString("description"),r.getString("farmer_name"));}
 public List<Product> all(String search)throws Exception{List<Product> list=new ArrayList<>();String sql="SELECT p.*,u.name farmer_name FROM products p JOIN users u ON p.farmer_id=u.id WHERE p.available=1 AND (p.name LIKE ? OR p.category LIKE ?) ORDER BY p.created_at DESC";
  try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement(sql)){String q="%"+(search==null?"":search)+"%";s.setString(1,q);s.setString(2,q);try(ResultSet r=s.executeQuery()){while(r.next())list.add(map(r));}}return list;}
 public List<Product> byFarmer(int id)throws Exception{List<Product> list=new ArrayList<>();String sql="SELECT p.*,u.name farmer_name FROM products p JOIN users u ON p.farmer_id=u.id WHERE p.farmer_id=? ORDER BY p.id DESC";try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setInt(1,id);try(ResultSet r=s.executeQuery()){while(r.next())list.add(map(r));}}return list;}
 public Product find(int id)throws Exception{try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("SELECT p.*,u.name farmer_name FROM products p JOIN users u ON p.farmer_id=u.id WHERE p.id=?")){s.setInt(1,id);try(ResultSet r=s.executeQuery()){return r.next()?map(r):null;}}}
 public void save(int id,int farmer,String name,String cat,double price,int stock,String desc)throws Exception{if(id==0){try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO products(farmer_id,name,category,price,stock,description) VALUES(?,?,?,?,?,?)")){s.setInt(1,farmer);s.setString(2,name);s.setString(3,cat);s.setDouble(4,price);s.setInt(5,stock);s.setString(6,desc);s.executeUpdate();}}else{try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("UPDATE products SET name=?,category=?,price=?,stock=?,description=? WHERE id=? AND farmer_id=?")){s.setString(1,name);s.setString(2,cat);s.setDouble(3,price);s.setInt(4,stock);s.setString(5,desc);s.setInt(6,id);s.setInt(7,farmer);s.executeUpdate();}}}
 public void delete(int id,int farmer)throws Exception{try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("DELETE FROM products WHERE id=? AND farmer_id=?")){s.setInt(1,id);s.setInt(2,farmer);s.executeUpdate();}}
}